#include "galaxy/Persistence.hpp"
#include <stdexcept>
#include <iostream>
using namespace galaxy;
int main(){Simulation s(42);auto home=s.add_colony_ship(7,{0,0},100,6);auto ferry=s.add_colony_ship(7,{0,0},100,6);s.enable_individual_workforce();s.upgrade_assignment_snapshot_format();Command c;c.id=100;c.execute_tick=1;c.issuer=Simulation::kServerAuthority;c.actor=ferry;c.target=home;c.action=Action::HostEmbarkPassengers;c.transport_id=900;c.passenger_ids={1};if(!s.submit(c))throw std::runtime_error("submit");s.step();auto snapshot=s.canonical_state();auto p=snapshot.find("galaxy-kernel-v34");if(p==std::string::npos)throw std::runtime_error("version");snapshot.replace(p,17,"galaxy-kernel-v32");p=snapshot.find("voyage|900|");if(p==std::string::npos)throw std::runtime_error("voyage");snapshot.erase(p,snapshot.find('\n',p)-p+1);bool rejected=false;try{auto restored=Simulation::from_snapshot(snapshot);(void)restored;}catch(const std::exception& e){rejected=std::string(e.what()).find("legacy v32 active voyage")!=std::string::npos;}if(!rejected)throw std::runtime_error("legacy active voyage not explicitly rejected");std::cout<<"PASS legacy active voyage rejected with explicit migration requirement\n";}
